from collections import deque

def transform(grid):
    h,w=len(grid),len(grid[0]); out=[row[:] for row in grid]
    zeros={(r,c) for r in range(h) for c in range(w) if grid[r][c]==0}
    outside=set(); q=deque()
    for r,c in zeros:
        if r in (0,h-1) or c in (0,w-1): outside.add((r,c)); q.append((r,c))
    while q:
        r,c=q.popleft()
        for dr,dc in ((1,0),(-1,0),(0,1),(0,-1)):
            nr,nc=r+dr,c+dc
            if 0<=nr<h and 0<=nc<w and grid[nr][nc]==0 and (nr,nc) not in outside:
                outside.add((nr,nc)); q.append((nr,nc))
    enclosed=zeros-outside
    if not enclosed: return out
    # 1-components in four-connectivity; activate those adjacent to enclosed regions.
    ones={(r,c) for r in range(h) for c in range(w) if grid[r][c]==1}
    seen=set(); active=set()
    for cell in ones:
        if cell in seen: continue
        comp=set([cell]); seen.add(cell); q=deque([cell])
        while q:
            r,c=q.popleft()
            for dr,dc in ((1,0),(-1,0),(0,1),(0,-1)):
                x=(r+dr,c+dc)
                if x in ones and x not in seen:
                    seen.add(x); comp.add(x); q.append(x)
        if any(abs(r-er)<=1 and abs(c-ec)<=1 for r,c in comp for er,ec in enclosed):
            active.update(comp)
    for r,c in enclosed:
        if any(0<=r+dr<h and 0<=c+dc<w and grid[r+dr][c+dc]==1
               for dr in (-1,0,1) for dc in (-1,0,1) if dr or dc):
            out[r][c]=3
    for r,c in active:
        for dr in (-1,0,1):
            for dc in (-1,0,1):
                nr,nc=r+dr,c+dc
                if 0<=nr<h and 0<=nc<w and grid[nr][nc]==0 and (nr,nc) in outside:
                    out[nr][nc]=2
    return out

def parse(s): return [[int(v) for v in row.split()] for row in s.strip().splitlines()]

def transform2(grid):
    h,w=len(grid),len(grid[0]); out=transform(grid)
    # close isolated diagonal gaps in the exterior-color outline
    for r in range(h):
        for c in range(w):
            if grid[r][c] != 0 or out[r][c] != 0: continue
            n2=sum(1 for dr in (-1,0,1) for dc in (-1,0,1) if (dr or dc) and 0<=r+dr<h and 0<=c+dc<w and out[r+dr][c+dc]==2)
            if n2>=3: out[r][c]=2
